(function(){function q(s){return document.querySelectorAll(s)}function toggleLoading(btn){if(!btn)return;btn.classList.toggle('is-loading');btn.disabled=!btn.disabled}window.saveCamControls=function(){var pre='camcontrol_';var enabled=[];q('input[type=checkbox]').forEach(function(cb){if(cb.id&&cb.id.indexOf(pre)===0&&cb.checked)enabled.push(cb.id.slice(pre.length));});var body='cmd=setsettings&controls='+encodeURIComponent(enabled.join(' '));var submit=document.querySelector('.button.is-primary');if(submit)toggleLoading(submit);fetch('cgi-bin/camcontrols.cgi',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:body}).then(function(){if(submit)toggleLoading(submit);if(window.updateCameraControls)try{window.updateCameraControls()}catch(e){console.log(e)}}).catch(function(e){if(submit)toggleLoading(submit);console.error(e)});} })();